Lemma Y_DOF : dof_stmt H.
Proof. exact (dof_spec H HH (ah_memcpy H HH) (ah_memset H HH) (ah_memmove H HH) Y_ASSIGNA Y_OPI Y_VL Y_TKC Y_TKI Y_FS2). Qed.
Lemma Y_PF : pf_stmt. Proof. exact (pf_spec (ah_memcpy H HH) Y_ASSIGNA (ah_memmove H HH)). Qed.
Lemma Y_OFI : ofi_stmt H. Proof. exact (ofi_spec H HH Y_FS0). Qed.
Lemma Y_OTF : otf_stmt H. Proof. exact (otf_spec H HH Y_FS0 (token_list_exists_c H HH)). Qed.
Lemma Y_IPF : ipf_stmt H.
Proof. exact (ipf_spec H HH Y_SSF8 Y_SS00 Y_FS7 Y_FREE7 (ah_memcpy H HH) Y_ASSIGNA Y_DOF Y_PF Y_OFI Y_OTF). Qed.
