(* [comment removed for export] *)
Lemma bput_closed : forall MX CX MA' MR, bput_stmt H MX CX MA' MR.
Proof.
  intros MX CX MA' MR.
  exact (bput_spec H HH MX CX MA' MR (ah_memset H HH) cl_spec (obinit_spec (ah_memset H HH)) (on_finish_impl_spec (ah_memset H HH))
           psl_seg1 (psl_seg2 (ah_memcpy H HH) Y_ASSIGNA) Y_ISL pf_seg1 (pf_seg2 (ah_memcpy H HH) Y_ASSIGNA) Y_IPF Y_FH
           (pb_seg1 (ah_memset H HH)) (pb_seg2 (ah_memset H HH)) Y_OBI Y_PCH Y_OCB).
Qed.
(* [comment removed for export] *)
Lemma sro_closed : forall MX CX MR, sro_stmt H MX CX MA MR.
Proof. intros MX CX MR. exact (sro_spec H HH Y_FS0 H7 H8 (fun MX' CX' MA' R' => bput_stmtR_of H MX' CX' MA' R' (bput_closed MX' CX' MA' R')) MX CX MA MR). Qed.
Lemma Y_MI : make_impl_stmt H. Proof. exact (make_impl_spec H HH). Qed.
Lemma Y_FBP : fb_prepare_stmt H. Proof. exact (fb_prepare_spec H HH Y_FS0 H7). Qed.
Lemma Y_BSD : stream_dtor_stmt H. Proof. exact (stream_dtor_spec H HH Y_FS2 ATR). Qed.
Lemma Y_DSS : destroy_alloc_ssvc_stmt H. Proof. exact (destroy_alloc_ssvc_spec H HH ATR). Qed.
Lemma Y_HSL : hs_local (AHStat FT). Proof. exact (AHStat_local FT FT_local). Qed.
